begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.courses(id,owner_id,title) values('a5000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','Quiz generation');
insert into public.files(id,course_id,uploaded_by,storage_bucket,storage_path,original_filename,mime_type,size_bytes,status)
 values('a5000000-0000-0000-0000-000000000002','a5000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','learning-files','11111111-1111-1111-1111-111111111111/a5000000-0000-0000-0000-000000000001/a5000000-0000-0000-0000-000000000002.txt','test.txt','text/plain',10,'ready');
insert into public.materials(id,course_id,created_by,type,title,file_id) values('a5000000-0000-0000-0000-000000000003','a5000000-0000-0000-0000-000000000001','11111111-1111-1111-1111-111111111111','source_document','Source','a5000000-0000-0000-0000-000000000002');
insert into public.source_documents(id,material_id,processing_status,indexing_status,extracted_text,completed_at) values('a5000000-0000-0000-0000-000000000004','a5000000-0000-0000-0000-000000000003','ready','ready','X is B',now());
insert into public.document_chunks(id,document_id,chunk_index,content,page_number,embedding) values('a5000000-0000-0000-0000-000000000005','a5000000-0000-0000-0000-000000000004',0,'X is B',2,array_fill(0.1::real,array[1536])::extensions.vector);
create temporary table ctx(k text primary key,v jsonb);
insert into ctx values('body','{"action":"generate","source_material_id":"a5000000-0000-0000-0000-000000000003","request_id":"a5000000-0000-0000-0000-000000000006","count":1}'),
 ('config','{"version":"quizzes-v1","maxSourceCharacters":500000,"maxCalls":10,"tokenBudget":100000}'),
 ('cp','{"planned":true,"questions":[{"question":"X?","options":["A","B","C","D"],"correctIndex":1,"explanation":"X is B","source_chunk_ids":["a5000000-0000-0000-0000-000000000005"]}]}');
insert into ctx values('job',public.quiz_action('11111111-1111-1111-1111-111111111111',(select v from ctx where k='body'),(select v from ctx where k='config')));
select is(public.quiz_action('11111111-1111-1111-1111-111111111111',(select v from ctx where k='body'),(select v from ctx where k='config')),(select v from ctx where k='job'),'Request replay returns original job');
select is((select count(*) from public.usage_events where user_id='11111111-1111-1111-1111-111111111111' and kind='quizzes'),1::bigint,'Retry consumes once');
select throws_ok($$select public.quiz_action('22222222-2222-2222-2222-222222222222',(select v from ctx where k='body'),(select v from ctx where k='config'))$$,'P0001','TARGET_NOT_FOUND','Foreign source rejected');
select throws_ok($$select public.quiz_action('11111111-1111-1111-1111-111111111111',(select v||'{"count":2}' from ctx where k='body'),(select v from ctx where k='config'))$$,'P0001','REQUEST_CONFLICT','Changed replay rejected');
insert into ctx values('claim',public.claim_quiz_job());
select ok(public.reserve_quiz_call((select (v->>'id')::uuid from ctx where k='claim'),(select (v->>'lease_token')::uuid from ctx where k='claim'),100),'Budget reservation');
select throws_ok($$select public.save_quiz_step((select (v->>'id')::uuid from ctx where k='claim'),(select (v->>'lease_token')::uuid from ctx where k='claim'),'{"questions":[{"question":"X?","options":["A","B","C","D"],"correctIndex":1}]}','completed')$$,'P0001','INVALID_QUESTION','Generated question needs explanation and provenance');
select is((select count(*) from public.learning_quizzes where source_material_id='a5000000-0000-0000-0000-000000000003'),0::bigint,'Invalid completion rolls back');
select ok(public.save_quiz_step((select (v->>'id')::uuid from ctx where k='claim'),(select (v->>'lease_token')::uuid from ctx where k='claim'),(select v from ctx where k='cp'),'completed'),'Atomic completion');
select ok(not public.save_quiz_step((select (v->>'id')::uuid from ctx where k='claim'),(select (v->>'lease_token')::uuid from ctx where k='claim'),(select v from ctx where k='cp'),'completed'),'Late worker rejected');
select is((select questions->0->>'explanation' from public.learning_quizzes where source_material_id='a5000000-0000-0000-0000-000000000003'),'X is B','Explanation persisted');
select is((select questions->0->'sources'->0->>'page_number' from public.learning_quizzes where source_material_id='a5000000-0000-0000-0000-000000000003'),'2','Source page persisted');
select is(jsonb_array_length(public.quiz_action('11111111-1111-1111-1111-111111111111','{"action":"list","source_material_id":"a5000000-0000-0000-0000-000000000003"}')),1,'Completed job discoverable after reload');
update public.plan_limits set value=1 where kind='quizzes' and plan='free';
select throws_ok($$select public.quiz_action('11111111-1111-1111-1111-111111111111',(select v||jsonb_build_object('request_id',gen_random_uuid()) from ctx where k='body'),(select v from ctx where k='config'))$$,'P0001','QUOTA_EXCEEDED','Quota enforced');
update public.plan_limits set value=50 where kind='quizzes' and plan='free';
insert into ctx values('changed',public.quiz_action('11111111-1111-1111-1111-111111111111',(select v||jsonb_build_object('request_id',gen_random_uuid()) from ctx where k='body'),(select v from ctx where k='config')));
update ctx set v=public.claim_quiz_job() where k='claim';
update public.document_chunks set content='Changed' where id='a5000000-0000-0000-0000-000000000005';
select ok(public.save_quiz_step((select (v->>'id')::uuid from ctx where k='claim'),(select (v->>'lease_token')::uuid from ctx where k='claim'),(select v from ctx where k='cp'),'completed'),'Changed source handled');
select is((select error_code from public.quiz_generation_jobs where id=(select (v->>'id')::uuid from ctx where k='changed')),'SOURCE_CHANGED','Source change blocks publishing');
insert into ctx values('cancel',public.quiz_action('11111111-1111-1111-1111-111111111111',(select v||jsonb_build_object('request_id',gen_random_uuid()) from ctx where k='body'),(select v from ctx where k='config')));
update ctx set v=public.claim_quiz_job() where k='claim';
select is(public.quiz_action('11111111-1111-1111-1111-111111111111',jsonb_build_object('action','cancel','job_id',(select v->>'id' from ctx where k='cancel')))->>'status','cancelled','Cancellation stored');
select ok(not public.save_quiz_step((select (v->>'id')::uuid from ctx where k='claim'),(select (v->>'lease_token')::uuid from ctx where k='claim'),(select v from ctx where k='cp'),'completed'),'Cancelled worker cannot publish');
set local role authenticated;
set local request.jwt.claims='{"sub":"22222222-2222-2222-2222-222222222222","role":"authenticated"}';
select throws_ok($$select * from public.quiz_generation_jobs$$,'42501',null,'Job internals private');
select throws_ok($$select public.claim_quiz_job()$$,'42501',null,'Worker RPC private');
select throws_ok($$select public.quiz_action(auth.uid(),'{}')$$,'42501',null,'Owner cannot be forged via public RPC');
select is((select count(*) from public.learning_quizzes where source_material_id='a5000000-0000-0000-0000-000000000003'),0::bigint,'Foreign quiz hidden');
reset role;
delete from public.materials where id='a5000000-0000-0000-0000-000000000003';
select is((select count(*) from public.quiz_generation_jobs where course_id='a5000000-0000-0000-0000-000000000001'),0::bigint,'Source deletion cascades to jobs');
select * from finish();
rollback;
